</main></div></div><div class="modal-shell" id="zynkoReportPreviewModal" aria-hidden="true"><div class="modal-card zynko-report-modal" role="dialog" aria-modal="true" aria-labelledby="zynkoReportTitle"><div class="modal-head"><div class="modal-title-with-icon"><span class="modal-title-icon"><i class="fa-solid fa-file-pdf"></i></span><span class="modal-title-copy"><b id="zynkoReportTitle">Vista previa de reporte PDF</b><small>Seleccione orientación y tamaño antes de descargar.</small></span></div><button type="button" class="modal-close" aria-label="Cerrar"><i class="fa-solid fa-xmark"></i></button></div><div class="zynko-report-modal-body"><div class="zynko-report-controls"><div class="field"><label for="zynkoReportPaper">Tamaño</label><select id="zynkoReportPaper"><option value="letter">Carta</option><option value="a4">A4</option></select></div><div class="field"><label for="zynkoReportOrientation">Orientación</label><select id="zynkoReportOrientation"><option value="portrait">Vertical</option><option value="landscape">Horizontal</option></select></div></div><iframe id="zynkoReportFrame" title="Vista previa del PDF" loading="lazy"></iframe></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cerrar</button><a id="zynkoReportDownload" href="#" class="primary" download><i class="fa-solid fa-download"></i> Descargar PDF</a></div></div></div>
<script>
(()=>{const modal=document.getElementById('zynkoReportPreviewModal');if(!modal)return;const frame=modal.querySelector('#zynkoReportFrame'),download=modal.querySelector('#zynkoReportDownload'),paper=modal.querySelector('#zynkoReportPaper'),orientation=modal.querySelector('#zynkoReportOrientation');let base='';function update(){if(!base)return;const u=new URL(base,location.href);u.searchParams.set('preview','1');u.searchParams.set('paper',paper.value);u.searchParams.set('orientation',orientation.value);frame.src=u.toString();u.searchParams.delete('preview');download.href=u.toString()};document.addEventListener('click',e=>{const btn=e.target.closest('.zynko-report-preview-open');if(!btn)return;e.preventDefault();base=btn.dataset.reportUrl||btn.getAttribute('href');update();modal.classList.add('open');document.body.classList.add('modal-open');modal.setAttribute('aria-hidden','false')});for(const c of [paper,orientation])c.addEventListener('change',update);modal.querySelectorAll('.modal-close').forEach(b=>b.addEventListener('click',()=>{modal.classList.remove('open');document.body.classList.remove('modal-open');modal.setAttribute('aria-hidden','true');frame.src='about:blank'}));})();
</script>
